export const services: Service[] = baseServices.map(service => {
  const content = seoPageContent[service.slug] || semPageContent[service.slug];
  if (!content) return service;
  return {
    ...service,
    title: content.title,
    heading: `${content.heading} ${content.tagline}`,
    intro: content.description,
    definition: content.introText,
    scope: content.scope,
    process: content.steps.map(step => [step.label, step.text] as [string, string]),
    deliverables: content.steps.map(step => step.output),
    measures: content.measures,
    faqs: content.faqs,
    cta: content.cta,
  };
});
